--------------------------------------------------------------------------------
-- Script : create_users.sql
-- Author : Tim PANDAWA
-- Date   : 2026-11-01
-- Purpose: Buat akun workspace APEX + daftarkan role DEMO
-- Note   : GENERATED by pandawa-apexlang generator dari app.yaml. Jangan edit manual.
--------------------------------------------------------------------------------

set serveroutput on

-- Jalankan sebagai workspace administrator: SQL Workshop > SQL Scripts > Upload > Run > View Results.
-- c_password null = password acak per user (dicetak sekali). Isi untuk password sama semua user.
-- JANGAN commit password ke repository. Aman dijalankan ulang (user yang ada tidak diubah).
declare
   c_password     constant varchar2(100) := null;
   c_email_domain constant varchar2(100) := 'example.com';
   c_workspace    constant varchar2(100) := null;  -- isi bila dijalankan via SQLcl
   c_extra_admin  constant varchar2(255) := null;  -- akun workspace lain yang juga dijadikan ADMIN
   -- Akun yang menjalankan script ini (developer di SQL Workshop) otomatis didaftarkan sebagai ADMIN,
   -- supaya tidak terkunci begitu mode bootstrap berakhir (ADMIN pertama terdaftar).
   l_runner       varchar2(255) := upper(sys_context('APEX$SESSION', 'APP_USER'));

   procedure add_user (
      p_user       in varchar2
     ,p_roles      in varchar2
     ,p_first_name in varchar2
   )
   is
      l_user   varchar2(255) := upper(p_user);
      l_pwd    varchar2(100);
      l_exists number;
   begin
      select count(*)
        into l_exists
        from apex_workspace_apex_users
       where user_name = l_user;

      if l_exists = 0 then
         l_pwd := coalesce(c_password, 'Px' || dbms_random.string('x', 8) || '#' || trunc(dbms_random.value(10, 99)));
         apex_util.create_user(
            p_user_name                    => l_user
           ,p_first_name                   => p_first_name
           ,p_last_name                    => 'DEMO'
           ,p_email_address                => lower(l_user) || '@' || c_email_domain
           ,p_web_password                 => l_pwd
           ,p_change_password_on_first_use => 'N');
         dbms_output.put_line(rpad(l_user, 20) || ' dibuat      password: ' || l_pwd);
      else
         dbms_output.put_line(rpad(l_user, 20) || ' sudah ada   (password tidak diubah)');
      end if;

      if p_roles is not null then
         for r in (select trim(column_value) role_code from table(apex_string.split(p_roles, ',')))
         loop
            merge into apx_demo_user_roles t
            using (select l_user username, upper(r.role_code) role_code from dual) s
               on (t.username = s.username and t.role_code = s.role_code)
             when not matched then
                  insert (username, role_code) values (s.username, s.role_code);
            dbms_output.put_line(rpad(' ', 20) || ' role: ' || upper(r.role_code));
         end loop;
      end if;
   end add_user;
begin
   if c_workspace is not null then
      apex_util.set_workspace(p_workspace => c_workspace);
   end if;

   add_user('DEMO_ADMIN',          'ADMIN',                     'Admin');
   add_user('DEMO_REQ',            'REQUESTER',                 'Requester');
   add_user('DEMO_MGR',            'MANAGER',                   'Manager');
   add_user('DEMO_DIR',            'DIRECTOR',                  'Director');
   add_user('DEMO_WH',             'WAREHOUSE',                 'Warehouse');
   add_user('DEMO_E2E',            null,                        'E2E Test');

   for r in (select upper(column_value) username
               from table(apex_t_varchar2(l_runner, c_extra_admin))
              where column_value is not null
                and upper(column_value) <> 'NOBODY')
   loop
      merge into apx_demo_user_roles t
      using (select r.username username, 'ADMIN' role_code from dual) s
         on (t.username = s.username and t.role_code = s.role_code)
       when not matched then
            insert (username, role_code) values (s.username, s.role_code);
      dbms_output.put_line(rpad(r.username, 20) || ' role: ADMIN (akun yang sudah ada / yang menjalankan script)');
   end loop;

   commit;
end;
/
